```javascript
// Go binding (store.go)
package main

/*
#include "kv_store.h"
*/
import "C"
import (
    "sync"
)

type Store struct {
    cstore *C.KVStore
    mu     sync.Mutex
}

func (s *Store) Put(key, value string) error {
    s.mu.Lock()
    defer s.mu.Unlock()
    ck := C.CString(key)
    cv := C.CString(value)
    defer C.free(unsafe.Pointer(ck))
    defer C.free(unsafe.Pointer(cv))
    if C.kv_put(s.cstore, ck, cv) != 0 {
        return fmt.Errorf("put failed")
    }
    return nil
}

func (s *Store) Get(key string) (string, bool, error) {
    s.mu.Lock()
    defer s.mu.Unlock()
    ck := C.CString(key)
    defer C.free(unsafe.Pointer(ck))
    var found C.int
    val := C.kv_get(s.cstore, ck, &found)
    if found == 0 {
        return "", false, nil
    }
    goVal := C.GoString(val)
    C.kv_free_value(val)
    return goVal, true, nil
}
```

